A probability density function is $f(x) = k$ for $0 \le x < 2$ and $f(x) = 3k$ for $2 \le x \le 6$, and $0$ elsewhere.
Find $k$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=0.78cm, y=1.2cm]
\draw[->] (-0.7,0) -- (7.4,0) node[right] {$x$};
\draw[->] (0,-0.4) -- (0,2.6) node[above] {$f(x)$};
\draw[thick] (-0.6,0) -- (0,0);
\draw[thick] (0,0.6) -- (2,0.6);
\draw[thick] (2,1.8) -- (6,1.8);
\draw[dashed] (0,0.6) -- (0,0);
\draw[dashed] (2,0.6) -- (2,1.8);
\draw[dashed] (6,1.8) -- (6,0);
\draw[thick] (6,0) -- (7.2,0);
\node[left] at (0,0.6) {$k$};
\node[left] at (0,1.8) {$3k$};
\node[below] at (2,0) {$2$};
\node[below] at (6,0) {$6$};
\end{tikzpicture}
[/tikz]

